window.ScripturaLexicons.BDAG_PART_0284 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-01\" data-source=\"BDAG\" data-search=\"περισσοτέρως advérbio ainda mais; muito mais; especialmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περισσοτέρως</td><td>advérbio</td><td>ainda mais; muito mais; especialmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-02\" data-source=\"BDAG\" data-search=\"περισσῶς advérbio extremamente; desmedidamente; ainda mais BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περισσῶς</td><td>advérbio</td><td>extremamente; desmedidamente; ainda mais</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-03\" data-source=\"BDAG\" data-search=\"περιστέλλω verbo cobrir por todos os lados; vestir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιστέλλω</td><td>verbo</td><td>cobrir por todos os lados; vestir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-04\" data-source=\"BDAG\" data-search=\"περιστερά, ᾶς, ἡ substantivo feminino pomba; pombo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιστερά, ᾶς, ἡ</td><td>substantivo feminino</td><td>pomba; pombo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-05\" data-source=\"BDAG\" data-search=\"περισχίζω verbo rasgar de alto a baixo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περισχίζω</td><td>verbo</td><td>rasgar de alto a baixo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-06\" data-source=\"BDAG\" data-search=\"περισῴζω verbo salvar; resgatar da morte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περισῴζω</td><td>verbo</td><td>salvar; resgatar da morte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-07\" data-source=\"BDAG\" data-search=\"περιτειχίζω verbo cercar com muro; envolver BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιτειχίζω</td><td>verbo</td><td>cercar com muro; envolver</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-08\" data-source=\"BDAG\" data-search=\"περιτέμνω verbo circuncidar; circuncidar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιτέμνω</td><td>verbo</td><td>circuncidar; circuncidar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-09\" data-source=\"BDAG\" data-search=\"περιτίθημι verbo colocar ao redor; conferir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιτίθημι</td><td>verbo</td><td>colocar ao redor; conferir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-10\" data-source=\"BDAG\" data-search=\"περιτομή, ῆς, ἡ substantivo feminino circuncisão; circuncidados BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιτομή, ῆς, ἡ</td><td>substantivo feminino</td><td>circuncisão; circuncidados</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-11\" data-source=\"BDAG\" data-search=\"περιτρέπω verbo transformar; alterar de um estado para outro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιτρέπω</td><td>verbo</td><td>transformar; alterar de um estado para outro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-12\" data-source=\"BDAG\" data-search=\"περιτρέχω verbo correr em volta; percorrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιτρέχω</td><td>verbo</td><td>correr em volta; percorrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-13\" data-source=\"BDAG\" data-search=\"περιφέρω verbo transportar de um lado para outro; levar consigo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιφέρω</td><td>verbo</td><td>transportar de um lado para outro; levar consigo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-14\" data-source=\"BDAG\" data-search=\"περιφρονέω verbo desdenhar; desprezar; desconsiderar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιφρονέω</td><td>verbo</td><td>desdenhar; desprezar; desconsiderar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-15\" data-source=\"BDAG\" data-search=\"περιχαρής, ές adjetivo muito alegre; jubiloso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιχαρής, ές</td><td>adjetivo</td><td>muito alegre; jubiloso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-16\" data-source=\"BDAG\" data-search=\"περίχωρος, ον adjetivo; substantivo vizinho; região circunvizinha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περίχωρος, ον</td><td>adjetivo; substantivo</td><td>vizinho; região circunvizinha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-17\" data-source=\"BDAG\" data-search=\"περίψημα, ατος, τό substantivo neutro escória; resgate; humilde servidor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περίψημα, ατος, τό</td><td>substantivo neutro</td><td>escória; resgate; humilde servidor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-18\" data-source=\"BDAG\" data-search=\"περπερεύομαι verbo vangloriar-se; gabar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περπερεύομαι</td><td>verbo</td><td>vangloriar-se; gabar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-19\" data-source=\"BDAG\" data-search=\"Περσίς, ίδος, ἡ nome próprio feminino Pérside BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Περσίς, ίδος, ἡ</td><td>nome próprio feminino</td><td>Pérside</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0284-20\" data-source=\"BDAG\" data-search=\"πέρυσι advérbio no ano passado; há um ano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέρυσι</td><td>advérbio</td><td>no ano passado; há um ano</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0284-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περισσοτέρως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περισσοτέρως</span>, advérbio de <span class=\"greek\">περισσότερος</span> (veja os dois verbetes anteriores; Diod S 13, 108; Athen. 5, 19s.; PGiss 25, 12 [II d.C.]).<br>① (Ainda) mais, em sentido comparativo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:14</a>, variante textual; em grau muito maior, muito mais, em grau muito superior (aos adversários de Paulo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:23</a>; (aos da própria idade) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:14</a>. (Oposto a <span class=\"greek\">ἧσσον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:15</a> (<span class=\"greek\">ἀγαπάω</span> 1a<span class=\"greek\">α</span>). Com valor intensificador, «tanto (mais)», «muito mais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:1</a>; 13:19.<br>② Especialmente, com valor elativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:12</a>; 2:4; 7:15; «ainda mais» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:17</a>. Forma reforçada <span class=\"greek\">περισσοτέρως</span> <span class=\"greek\">μᾶλλον</span> «ainda muito mais» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:13</a>.—DELG s.v. <span class=\"greek\">περί</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περισσῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περισσῶς</span>, advérbio que assinala grau excepcionalmente elevado numa escala de intensidade, extremamente, desmedidamente, muito (veja os três verbetes anteriores; Eur., Hdt. e outros; Polyb. 1, 29, 7; 32, 15, 4; Athen. 11 p. 501d; PTebt 488; LXX; Theod.; Philo, Det. Pot. Ins. 15 e outros; Jos., Ant. 1, 258) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:11</a>.—Comparativo (<span class=\"greek\">περισσός</span> 3), mais, ainda mais: <span class=\"greek\">περισσῶς</span> <span class=\"greek\">ἔκραζον</span> «gritavam ainda mais alto» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:23</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:14</a>. <span class=\"greek\">π</span>. <span class=\"greek\">ἐξεπλήσσοντο</span> «ficavam ainda mais espantados» 10:26.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιστέλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιστέλλω</span>, futuro <span class=\"greek\">περιστελῶ</span>; 2.º aoristo singular <span class=\"greek\">περιέστειλες</span> (Tob 12:13 <span class=\"hebrew\" dir=\"rtl\">א</span>), imperativo, 2.ª pessoa do singular <span class=\"greek\">περίστειλον</span> Sir 38:16; 2.º aoristo passivo, subjuntivo, 2.ª pessoa do singular <span class=\"greek\">περισταλῇς</span> Ezk 29:5, particípio neutro <span class=\"greek\">περισταλέν</span> (TestJob) (Hom. e outros; Herm. Wr. 492, 21 Sc.; PGM 4, 3138; LXX; PsSol 16:10; TestJob 52:11; Jos., Ant. 19, 237, C. Ap. 2, 269), cobrir por todos os lados, vestir, <span class=\"greek\">τινά</span> «alguém», acerca de vestuário (Diod S 19, 11, 7 <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">περιέστειλεν</span>; Jos., Ant. 17, 59) B 3:4 (Is 58:8).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιστερά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιστερά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (Hdt., Aristoph.+), ave da família Columbidae (Aristot., HA 562b, 3–7 distingue-a de <span class=\"greek\">τρυγών</span> [rola] e <span class=\"greek\">φάττα</span>; veja também 593a, 16. A pomba-das-rochas é a espécie geralmente vista em locais públicos). Frequentemente traduzida tanto por «pombo» quanto por «pomba» (mas preferir o segundo termo ao primeiro sugere uma diferença que não se pode determinar com precisão pelo uso nos nossos textos); utilizada para sacrifícios e, por isso, vendida no templo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:14</a>, 16. Dalman, Arbeit VII (veja <span class=\"greek\">οἰκία</span> 1a, final).—Sobre <span class=\"greek\">δύο</span> <span class=\"greek\">νοσσοὶ</span> <span class=\"greek\">περιστερῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:24</a>, veja <span class=\"greek\">νοσσός</span>.<br>O pombo, que do ponto de vista das ciências naturais na Antiguidade não possui bile, era para os primeiros cristãos símbolo de várias virtudes (veja WBauer, D. Leben Jesu 1909, 117): <span class=\"greek\">ἀκέραιοι</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">περιστεραί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:16</a>; cf. IPol 2:2. Por isso o Espírito Santo, ao aparecer no batismo de Jesus, tomou a forma de pombo/pomba (WTelfer, The Form of a Dove: JTS 29, 1928, 238–42; LKeck, NTS 17, ’70/71, 41–67, «descida semelhante à de uma pomba») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:32</a>; GEb 18, 36.—HUsener, Das Weihnachtsfest2 1911, 56ss.; HGressmann, Die Sage v. d. Taufe Jesu und d. vorderoriental. Taubengöttin: ARW 20, 1920/21, 1–40; 323–59.—Sobre o simbolismo, cf. o emprego de Gen 1:2 em Qumran (4Q521, 2:6), veja DAllison, Bar 8, ’92, 58–60; JMarcus, NTS 41, ’95, 512–21.<br><span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">π</span>. (sobre Maria) GJs 8:1. <span class=\"greek\">π</span>. <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">απὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ῥάβδου</span> «uma pomba saiu do cajado (de José)» 9:1 (símbolo do nascimento de um rei). Em MPol 16:1, a leitura <span class=\"greek\">περὶ</span> <span class=\"greek\">στύρακα</span>, inserção conjectural de Wordsworth, obteve certa aprovação imerecida. Os manuscritos gregos apresentam <span class=\"greek\">περιστερὰ</span> <span class=\"greek\">καί</span>, que Bihlmeyer põe entre colchetes (veja JKleist, tradução de ’48, nota ad loc.). Subjaz a isso a concepção do pombo como representação da alma (cf., de certa maneira, Quint. Symyrn. 8, 202s. <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἕλκεος</span> <span class=\"greek\">ἐξεποτήθη</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μελέων</span> = «a alma voou para fora do corpo através do ferimento»).—GWeicker, D. Seelenvogel 1902, 26s.; HGünter, Die christl. Legende des Abendlandes 1910, 13; 45; 86; 142; 148; 191; FSühling, D. Taube als. relig. Symbol im christl. Altertum 1930.—Kl. Pauly V 534–36; BHHW III 1934. SEG XLII, 1789 (inscrições e bibliografia sobre pombos, inclusive suas funções religiosas; veja FChamoux, CRAI ’92, 623–42).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περισχίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περισχίζω</span>, 1.º aoristo médio <span class=\"greek\">περιεσχισάμην</span> (voz média desde Hdt., Pla.; também Ezk 47:15; 48:1; TestZeb 4:5; Mel, P. 17, 116 e outros; papiros), rasgar algo por todos os lados, rasgar, romper: <span class=\"greek\">περιεσχίσαντο</span> <span class=\"greek\">ἐπάνωθεν</span> <span class=\"greek\">ἕω</span> <span class=\"greek\">κάτω</span> «rasgaram (as próprias vestes) de cima a baixo» GJs 24:3 (veja deStrycker p. 266 n. 4 e p. 240).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περισῴζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περισῴζω</span> (X. e outros; 1 Km 30:17, variante textual; Ps 114:4 Aq.; ViOb 3 [p. 82, 6 Sch.]; Joseph.), salvar, resgatar (da morte) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:51</a>, variante textual.—DELG s.v. <span class=\"greek\">σῶς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιτειχίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιτειχίζω</span>, 1.º aoristo <span class=\"greek\">περιετείχισα</span>; perfeito passivo <span class=\"greek\">περιτετείχισμαι</span> (Thu., Aristoph. e outros; papiros, LXX; Jos., Bell. 6, 323).<br>① Construir um muro sólido ao redor de um lugar, cercar com muralha, acerca de uma cidade: <span class=\"greek\">περιτετειχισμένη</span> <span class=\"greek\">κύκλῳ</span> «cercada com muralha» Hs 9, 12, 5 (BGU 993 III, 1 [II a.C.] <span class=\"greek\">τόπος</span> <span class=\"greek\">περιτετειχισμένος</span>).<br>② Cercar com alguma coisa que envolve, circundar, extensão figurada de 1: <span class=\"greek\">τούτοις</span> (isto é, <span class=\"greek\">ἀγγέλοις</span>) <span class=\"greek\">περιτετείχισται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> Hs 9, 12, 6. Acerca do mar de chamas proveniente da pira: <span class=\"greek\">κύκλῳ</span> <span class=\"greek\">περιετείχισε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μάρτυρος</span> «cercou completamente o corpo do mártir» MPol 15:2 (com <span class=\"greek\">κύκλῳ</span>, como em Thu. 2, 78).—DELG s.v. <span class=\"greek\">τεῖχος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιτέμνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιτέμνω</span>, 2.º aoristo <span class=\"greek\">περιέτεμον</span>; perfeito <span class=\"greek\">περιτέτμηκα</span> LXX. Passivo: 1.º futuro <span class=\"greek\">περιτμηθήσομαι</span>; 1.º aoristo <span class=\"greek\">περιετμήθην</span>; perfeito, 3.ª pessoa do singular <span class=\"greek\">περιτέτμηται</span> (Just., D. 28, 4); particípio <span class=\"greek\">περιτετμημένος</span> LXX; mais-que-perfeito, 3.ª pessoa do singular <span class=\"greek\">περιετέτμητο</span> (Just., D. 46, 3) (Hom. e outros), «cortar ao redor»; em nossa literatura e na LXX, às vezes figuradamente, apenas no sentido de cortar o prepúcio do órgão genital masculino, circuncidar (assim, ora na voz ativa, ora na média [«circuncidar-se»], desde Hdt. 2, 36, 2; 2, 104, 1 [acerca dos egípcios e vários outros povos]; também Diod S 1, 28, 3; 1, 55, 5; 3, 32, 4 [egípcios, colcos, <span class=\"greek\">Ἰουδαῖοι</span>]; Ptolemaeus, <span class=\"greek\">Περὶ</span> <span class=\"greek\">Ἡρώδου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλέως</span> [I d.C.]: 199 Fgm. 1 Jac.; Strabo 17, 2, 5; Philo Bybl. [cerca de 100 d.C.]: 790 Fgm. 2, 33 p. 812, 8 Jac. [em Eus., PE 1, 10, 33]; Sallust. 9 p. 18, 17; PLond I, 24, 12s. p. 32 [163 a.C.]; PTebt 291, 33; 292, 7; 20; 293, 12; 14; 19; Mitt-Wilck. I/2, 77 I, 11; III, 11 [149 d.C.]; OdeSol 11:2; TestLevi 6:3; Philo Alex.; Joseph.; Just.); em nossa literatura, provavelmente apenas nas vozes ativa e passiva.<br>ⓐ Literalmente, com acusativo de pessoa: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:59</a>; 2:21 (veja Schwyzer II 372); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:8</a>; 15:5; 16:3; 21:21; B 9:8 (Gen 17:23ss.). Passivo: ser circuncidado, fazer-se circuncidar (Orig., C. Cels. 1, 22, 4; Did., Gen. 75, 6; B-D-F §314): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:1</a>, 24, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:18b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:3</a> (Ptolemaeus, <span class=\"greek\">Περὶ</span> <span class=\"greek\">Ἡρώδου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλέως</span>: 199 Jac. [I d.C.] <span class=\"greek\">Ἰδουμαῖοι</span> <span class=\"greek\">ἀναγκασθέντες</span> <span class=\"greek\">περιτέμνεσθαι</span>. Veja SBelkin, JBL 54, ’35, 43–47); 5:2s.; 6:12, 13b. <span class=\"greek\">οἱ</span> <span class=\"greek\">περιτεμνόμενοι</span> «os que se fazem circuncidar», v. 13a. <span class=\"greek\">περιτετμημένος</span> «circuncidado, no estado de ter sido circuncidado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:18a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:13a</a>, variante textual.<br>ⓑ Figuradamente.<br><span class=\"greek\">α</span>. Acerca do batismo: <span class=\"greek\">περιετμήθητε</span> <span class=\"greek\">περιτομῇ</span> <span class=\"greek\">ἀχειροποιήτῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:11</a> (OCullmann, D. Tauflehre des NT ’48, 50–63).<br><span class=\"greek\">β</span>. Barnabé sustenta enfaticamente que as Escrituras não exigem circuncisão física: <span class=\"greek\">περιέτεμεν</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> 9:1a. O <span class=\"greek\">κύριος</span> diz <span class=\"greek\">περιτμήθητε</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">ὑμῶν</span> v. 1b. Evidentemente se tem em vista Jer 4:4 (cf. Dt 10:16; OdeSol 11:2); B aproxima-se mais desse texto em <span class=\"greek\">περιτμήθητε</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">ὑμῶν</span> «deixai-vos circuncidar para vosso Senhor» 9:5a, e na sua explicação <span class=\"greek\">περιτμήθητε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σκληροκαρδίαν</span> <span class=\"greek\">ὑμῶν</span> v. 5b. O que vale para o coração vale também para os ouvidos: <span class=\"greek\">περιέτεμεν</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀκοάς</span> 9:4. Cf. 10:12. Em 9:6 reconhece-se que a circuncisão é por vezes justificada assim: <span class=\"greek\">περιτέτμηται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σφραγῖδα</span>, e explica-se que <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">προβλέψας</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">περιέτεμεν</span> v. 7.—Schürer I 536ss.–40; Dssm., B 149ss. [BS 151–3]; UWilcken, HGunkel e PWendland, APF 2, 1903, 4–31; WOtto, Priester u. Tempel im hellenist. Ägypten I 1905, 213ss.; JMatthes, De Besnijdenis: Teylers Theol. Tijdschrift 6, 1908, 163–91; FDölger, Sphragis 1911, 51ss.; Billerb. IV 1928, 23–40; FBryk, D. Beschneidung b. Mann u. Weib ’31; JSasson, JBL 85, ’66, 473–76; JLieu, Circumcision, Women, and Salvation: NTS 40, ’94, 358–70.—RAC II, 159–69; BHHW I 223–25; TRE V 714–24. New Docs 3, 81; M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιτίθημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιτίθημι</span>, futuro, 3.ª pessoa do singular <span class=\"greek\">περιθήσει</span> LXX; 1.º aoristo <span class=\"greek\">περιέθηκα</span>; 2.º aoristo, imperativo, 2.ª pessoa do plural <span class=\"greek\">περίθετε</span>, particípio <span class=\"greek\">περιθείς</span>. Médio: futuro, 3.ª pessoa do singular <span class=\"greek\">περιθήσεται</span> Wsd 5:18; aoristo <span class=\"greek\">περιεθέμην</span> LXX. Passivo: imperfeito <span class=\"greek\">περιετιθέμην</span>; 1.º aoristo <span class=\"greek\">περιετέθην</span>; particípio perfeito <span class=\"greek\">περιτεθειμένος</span> (Hom. [em tmese]+).<br>① Colocar, pôr ao redor ou sobre, <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> «alguma coisa em torno de alguém ou alguma coisa»: <span class=\"greek\">φραγμὸν</span> <span class=\"greek\">αὐτῷ</span> (=<span class=\"greek\">τῷ</span> <span class=\"greek\">ἀμπελῶνι</span>) <span class=\"greek\">περιέθηκεν</span> «colocou uma cerca ao redor de uma vinha» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:1</a> (aqui o dativo deve ser suprido, como em Is 5:2.—SIG 898, 7s. <span class=\"greek\">τὸν</span> <span class=\"greek\">περίβολον</span> <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ν</span> <span class=\"greek\">περιέθηκε</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">τεμένει</span>). <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">περιετίθετο</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄργανα</span> «os instrumentos de madeira (ou a lenha) eram colocados em volta dele» MPol 13:3 (Appian, Iber. §132 <span class=\"greek\">ξύλα</span> <span class=\"greek\">περιθέντες</span> <span class=\"greek\">αὐτῇ</span>. Analogamente, Appian, Mithrid. 108 §512 <span class=\"greek\">ξύλα</span> <span class=\"greek\">περιθέντες</span> para incendiar alguma coisa). As barras ou limites impostos ao mar, 1 Cl 20:6 (cf. Job 38:10). <span class=\"greek\">σπόγγον</span> <span class=\"greek\">καλάμῳ</span> «colocar uma esponja numa cana» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:36</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:29</a>. Colocar ou dispor peças de roupa em volta de alguém ou sobre ele (Herodian 3, 7, 5 <span class=\"greek\">χλαμύδα</span>; OGI 383, 137; PSI 64, 17 [I a.C.]; Job 39:20; Jos., Ant. 6, 184; TestLevi 8:5, 6): <span class=\"greek\">χλαμύδα</span> <span class=\"greek\">περιέθηκαν</span> <span class=\"greek\">αὐτῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:28</a>. Especialmente acerca de faixas para a cabeça, coroas etc. (Ps.-Pla., Alcib. 2, 151a <span class=\"greek\">στέφανόν</span> <span class=\"greek\">τινι</span>. Várias vezes na LXX; PsSol 2:21; TestLevi 8:9; Philo, Mos. 2, 243) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:37</a>, variante textual (RBorger, TRu 52, ’87, 33s.). <span class=\"greek\">κρεῖττον</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">περιτεθῆναι</span> <span class=\"greek\">μύλον</span> 1 Cl 46:8.—Construções com preposições variadas substituem o dativo: <span class=\"greek\">π</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔριον</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξύλον</span> «colocar a lã sobre um bastão» B 8:1 (cf. Gen 41:42). <span class=\"greek\">π</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔριον</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλήν</span> 7:8 (citação que não pode ser identificada com certeza.—Sobre <span class=\"greek\">π</span>. <span class=\"greek\">περὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφ</span>. cf. Pla., Rep. 3, 406d).<br>② Fazer existir determinada condição relativamente a um objeto, pôr sobre ou ao redor, conceder, conferir, outorgar, <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> «alguma coisa a alguém»; extensão de 1, com a imagem de uma investidura em vigor (Hdt.+; SIG 985, 51; LXX; Philo, Aet. M. 41; Just., A II, 11, 7): <span class=\"greek\">τιμὴν</span> <span class=\"greek\">π</span>., com dativo, «demonstrar honra» (OGI 331, 23; BGU 1141, 19 [14 a.C.]; Esth 1:20; cf. também Thu. 6, 89, 2 <span class=\"greek\">ἀτιμίαν</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">π</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:23</a>. <span class=\"greek\">περιθεὶς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐπρέπειαν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κτίσει</span> <span class=\"greek\">αὐτοῦ</span> Hv 1, 3, 4.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιτομή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιτομή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (veja o verbete <span class=\"greek\">περιτέμνω</span>), «circuncisão» do prepúcio (Agatharchides [II a.C.] FHG 61; Timagenes [I a.C.]: 88 Fgm. 5 Jac.; Strabo 16, 2, 37 [no plural]; PTebt 314, 5 [II d.C.]; Gen 17:13; Ex 4:25s.; OdeSol 11:3; Artapanus [II a.C.]: 726 Fgm. 3, 10 Jac. [em Eus., PE 9, 27, 10]; Philo, Spec. Leg. 1, 8; 9; Jos., Ant. 1, 192; 214 [aqui no plural], C. Ap. 2, 137; 143; TestLevi 6:6; Just.).<br>① Circuncisão.<br>ⓐ Circuncisão como rito cultual (Iren. 1, 18, 3 [Harv. I 172, 16]; Orig., C. Cels. 5, 47, 1; Did., Gen. 237, 28) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:22</a>. <span class=\"greek\">διαθήκη</span> <span class=\"greek\">περιτομῆς</span> «aliança ou determinação da circuncisão» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:8</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">περιτομὴν</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">κηρύσσω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:11</a>.—B 9:4a, B 7. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:5</a> (veja <span class=\"greek\">ὀκταήμερος</span>); Dg 4:1, que também pode ser classificado em<br>ⓑ Estado de ter sido circuncidado = <span class=\"greek\">τὸ</span> <span class=\"greek\">περιτετμῆσθαι</span> (Diod S 3, 32, 4; Jos., Ant. 12, 241, C. Ap. 2, 137) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:25a</a>b, 26; 3:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:6</a>; 6:15. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φανερῷ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">περιτομή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:28</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">περιτομῆς</span> v. 27 (veja <span class=\"greek\">διά</span> A 3c). <span class=\"greek\">περιτομὴν</span> <span class=\"greek\">ἔχειν</span> IPhld 6:1. <span class=\"greek\">περιτομὴν</span> <span class=\"greek\">λαμβάνειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:23</a>. <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">περιτομῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:10a</a>; cf. v. 10b, onde <span class=\"greek\">ὄντι</span> deve ser suprido. Sobre v. 11, veja <span class=\"greek\">σημεῖον</span> 1. <span class=\"greek\">οἱ</span> <span class=\"greek\">Αἰγύπτιοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">π</span>. <span class=\"greek\">εἰσίν</span> B 9:6.<br>ⓒ Figuradamente, acerca da circuncisão espiritual (Just., D. 14, 4 <span class=\"greek\">δευτέρας</span> … <span class=\"greek\">περιτομῆς</span>; veja <span class=\"greek\">περιτέμνω</span> b<span class=\"greek\">β</span>): <span class=\"greek\">περιτομὴ</span> … <span class=\"greek\">οὐ</span> <span class=\"greek\">σαρκὸς</span> B 9:4b. <span class=\"greek\">περιτομὴ</span> <span class=\"greek\">καρδίας</span> (veja <span class=\"greek\">περιτέμνω</span> b<span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:29</a> (cf. OdeSol 11:1s.; JBarclay, NTS 44, ’98, 536–56 [Paulo e Fílon]). <span class=\"greek\">περιτομὴ</span> <span class=\"greek\">ἀχειροποίητος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:11a</a> = <span class=\"greek\">περ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> 11b, por meio da qual se entende o batismo (veja v. 12).<br>② Aquele que é circuncidado, substantivo abstrato empregado por concreto (cf., por exemplo, Appian, Bell. Civ. 3, 61 §249 <span class=\"greek\">ἐπεξέρχεσθαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">φόνον</span> = «proceder contra o homicídio [isto é, contra os homicidas]»); normalmente no plural, «os circuncidados».<br>ⓐ Literalmente, acerca dos judeus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:30</a>; 4:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:11</a> (em oposição a <span class=\"greek\">ἀκροβυστία</span> = «não judeus» nos três casos).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:12a</a>; 15:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:7</a>–9. <span class=\"greek\">οἱ</span> <span class=\"greek\">λεγόμενοι</span> <span class=\"greek\">ἀκροβυστία</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λεγομένης</span> <span class=\"greek\">περιτομῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">χειροποιήτου</span> «os que são chamados &#39;incircuncisão&#39; pela chamada &#39;circuncisão&#39; (cuja circuncisão) é puramente física (e) feita por mãos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:11</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">περιτομῆς</span> <span class=\"greek\">μόνον</span> «os que não somente pertencem aos &#39;circuncidados&#39;» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:12b</a>.—<span class=\"greek\">οἱ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">περιτομῆς</span> <span class=\"greek\">πιστοί</span> «os da &#39;circuncisão&#39; que creem», isto é, os cristãos judeus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.45\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:45</a>. Igualmente, <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">περιτομῆς</span> (<span class=\"greek\">ὄντες</span>) 11:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:10</a> (cf. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">π</span>. … <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἐθνῶν</span> Did., Gen. 182, 19).—EEllis, TU 102, ’68, 390–99.<br>ⓑ Figuradamente, acerca dos crentes em Jesus Cristo (como povo verdadeiramente circuncidado da promessa): <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">ἐσμεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">περιτομή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:3</a>.—Quanto ao sentido literal, veja <span class=\"greek\">περιτέμνω</span>.—DELG s.v. <span class=\"greek\">τέμνω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιτρέπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιτρέπω</span> (Lysias, Pla. e outros; Wsd 5:23; Philo), fazer passar de um estado ao seu oposto, transformar, <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> «alguém em alguma coisa» (BGU 1831, 8 [51 a.C.] <span class=\"greek\">εἰς</span> <span class=\"greek\">ἄπορον</span>; Vett. Val. 250, 9s.; Jos., Ant. 9, 72 <span class=\"greek\">τοὺς</span> <span class=\"greek\">παρόντας</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">χαρὰν</span> <span class=\"greek\">περιέτρεψε</span>; Tat. 22, 1 <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀδοξίαν</span>.—Niese lê o verbo simples em Jos., Ant. 2, 293): <span class=\"greek\">τὰ</span> <span class=\"greek\">πολλά</span> <span class=\"greek\">σε</span> <span class=\"greek\">γράμματα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μανίαν</span> <span class=\"greek\">περιτρέπει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:24</a> (veja <span class=\"greek\">μανία</span> e compare a expressão <span class=\"greek\">εἰς</span> <span class=\"greek\">μανίαν</span> <span class=\"greek\">περιτρέπειν</span> em Lucian, Abdic. 30 e Vi. Aesopi I G 55 P.).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιτρέχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιτρέχω</span>, imperfeito <span class=\"greek\">περιέτρεχον</span>; 2.º aoristo <span class=\"greek\">περιέδραμον</span>, particípio <span class=\"greek\">περιδραμών</span> (Hom. e outros).<br>① Estar em movimento ao redor, correr ou mover-se em volta, com acusativo da coisa ou pessoa em torno da qual se move (Hdt. 8, 128; Aristoph., Ran. 193 <span class=\"greek\">τὴν</span> <span class=\"greek\">λίμνην</span> <span class=\"greek\">κύκλῳ</span>; Athen. 5, 208b; PFlor 120, 7; GrBar 6:2): <span class=\"greek\">ἄγγελοι</span> <span class=\"greek\">περιέτρεχον</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἐκεῖσε</span> «anjos se moviam ao redor deles naquele lugar» ApcPt 5:18. <span class=\"greek\">ὧδε</span> <span class=\"greek\">κἀκεῖσε</span> <span class=\"greek\">περιτρ</span>. <span class=\"greek\">κύκλῳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πύλης</span> «correr de um lado para outro ao redor do portão» Hs 9, 3, 1.<br>② Estar em movimento rápido de um lado para outro numa região, correr por aí, percorrer (Cebes 14, 1; Am 8:12; Jer 5:1 <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ὁδοῖς</span>), com acusativo (Aristoph., Thesmoph. 657 <span class=\"greek\">τὴν</span> <span class=\"greek\">πύκνα</span> <span class=\"greek\">πᾶσαν</span>): <span class=\"greek\">ὅλην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χώραν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:55</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πρόβασι</span> (variante textual <span class=\"greek\">προβάτοις</span>) <span class=\"greek\">π</span>. «correr por entre as ovelhas» Hs 6, 1, 6.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιφέρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιφέρω</span>, particípio aoristo feminino, acusativo singular <span class=\"greek\">περιενέγκασαν</span> 2 Macc 7:27, levar de um lugar para outro, transportar para cá e para lá.<br>ⓐ Literalmente, com acusativo (Eur., Pla. e outros; Plut., Mor. 331c; SIG 1169, 65s., acerca de uma ponta de lança no rosto; Josh 24:33a; 2 Macc 7:27; TestSol; Ar. 5:3; Tat.): os enfermos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:55</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">δεσμά</span> «as correntes» IEph 11:2; cf. IMg 1:2; ITr 12:2. <span class=\"greek\">τὴν</span> <span class=\"greek\">νέκρωσιν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματι</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:10</a> (veja <span class=\"greek\">νέκρωσις</span> 1).<br>ⓑ Figuradamente (Epict. 2, 8, 12 <span class=\"greek\">θεὸν</span> <span class=\"greek\">π</span>. = «levar Deus consigo dentro de si»; 2, 16, 33; TestSol 12:3 C <span class=\"greek\">οἴησιν</span> [«opinião»] <span class=\"greek\">περιφερόμενοι</span>; Philo, Omnis Prob. Lib. 117 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀρετήν</span>; POxy 1664, 7, acerca de uma pessoa amada no coração): <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> «levar consigo o nome (de Cristo ou de cristão)» (provavelmente como pregadores itinerantes) IEph 7:1. O passivo, em imagem vívida (Jos., Ant. 19, 46 <span class=\"greek\">διὰ</span> <span class=\"greek\">λογισμῶν</span> <span class=\"greek\">περιφερόμενος</span>): <span class=\"greek\">περιφερόμενοι</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">ἀνέμῳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">διδασκαλίας</span> «levados para cá e para lá por todo e qualquer vento de doutrina» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:14</a> (ou será que <span class=\"greek\">περιφέρεσθαι</span> significa aqui «girar», tendo por trás a imagem de um cata-vento?); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:9</a>, variante textual.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιφρονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιφρονέω</span>, aoristo, 3.ª pessoa do singular <span class=\"greek\">περιεφρόνησε</span> ApcrEzk (Epiph. 70, 7), ter desdém por, desconsiderar, olhar de cima, desprezar (assim desde Thu. 1, 25, 4; POxy 71 II, 16; ApcrEzk [veja acima]; Jos., Ant. 4, 260), com genitivo (Ps.-Pla., Axioch. 372a <span class=\"greek\">τοῦ</span> <span class=\"greek\">ζῆν</span>; Plut., Thes. 1 [1, 5], Per. 169 [31, 1], Mor. 762e; 4 Macc 6:9; 7:16; 14:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:15</a>.—DELG s.v. <span class=\"greek\">φρήν</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιχαρής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιχαρής</span>, <span class=\"greek\">ές</span> (<span class=\"greek\">χαίρω</span>; Soph., Hdt. e outros; 3 Macc 5:44; TestSol; Philo, Rer. Div. Her. 3; Jos., Ant. 7, 206), muito contente, muito alegre: <span class=\"greek\">π</span>. <span class=\"greek\">γενέσθαι</span> (Diod S 20, 76, 6 <span class=\"greek\">π</span>. <span class=\"greek\">γενόμενος</span>; Chariton 6, 5, 1; Ael. Aristid. 50, 50 K. = 26 p. 517 D.; Job 3:22; 29:22; TestSol 1:8; Jos., Ant. 1, 284; 16, 358; PSI 887, 5 [VI d.C.]) Hv 3, 12, 2; seguido de infinitivo no genitivo em v 3, 8, 1.—DELG s.v. <span class=\"greek\">χαίρω</span> IB.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περίχωρος, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περίχωρος</span>, <span class=\"greek\">ον</span>, relativo a estar em volta de uma região, vizinho, circunvizinho (Gen 19:28); usado predominantemente como substantivo (<span class=\"greek\">οἱ</span> <span class=\"greek\">περίχωροι</span> «os vizinhos» Demosth. 19, 266; Plut., Cat. Maj. 351 [25, 3], Eum. 593 [15, 13]; Aelian, NA 10, 46; Cass. Dio 36, 33): <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. (subentende-se <span class=\"greek\">γῆ</span>; B-D-F §241, 1), «região ao redor, vizinhança» (LXX, que também emprega <span class=\"greek\">τὸ</span> <span class=\"greek\">περίχωρον</span> e <span class=\"greek\">τὰ</span> <span class=\"greek\">περίχωρα</span>; empréstimo no rabínico) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:55</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:14</a>, 37; 7:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:6</a>; 1 Cl 11:1; GPt 9:34.<br>Usado com genitivo, acerca de um rio, cuja região vizinha à direita e à esquerda é designada por <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>.: <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰορδάνου</span> (Gen 13:10s.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:5</a> (veja abaixo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:3</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">περίχωρος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Γερασηνῶν</span> «os gerasenos e as pessoas que moravam ao redor deles» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:37</a>. <span class=\"greek\">ὅλη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Γαλιλαίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:28</a> é tanto um genitivo epexegético, «toda a região ao redor, isto é, a Galileia», quanto «a região ao redor da Galileia» (Mateus entende a expressão neste último sentido e, em 4:24, inseriu <span class=\"greek\">ὅλη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">Συρία</span> em seu lugar); o genitivo epexegético provavelmente se apresenta em GJs 8:3 <span class=\"greek\">καθόλου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰουδαίας</span> «por toda a zona rural da Judeia» (veja deStrycker ad loc.). Por metonímia, designa os habitantes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:5</a>.—DELG s.v. <span class=\"greek\">χώρα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περίψημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περίψημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Vi. Aesopi G 35 P.; de <span class=\"greek\">περιψάω</span> = «limpar inteiramente, esfregar para limpar»), aquilo que é removido durante a limpeza, sujeira, escória (Jer 22:28 Sym.): <span class=\"greek\">πάντων</span> <span class=\"greek\">περίψημα</span> «a escória de todas as coisas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:13</a>.<br>Mas a reflexão sobre o fato de que a remoção do <span class=\"greek\">περίψ</span>. purifica o objeto ou a pessoa à qual estava aderido deu à palavra o significado adicional de resgate, bode expiatório, sacrifício (cf. Tob 5:19. Hesychius equipara-a a <span class=\"greek\">περικατάμαγμα</span> [cf. <span class=\"greek\">καταμάσσω</span> «limpar esfregando»] e a <span class=\"greek\">ἀντίλυτρα</span>, <span class=\"greek\">ἀντίψυχα</span>. Photius p. 425, 3 explica <span class=\"greek\">περίψ</span>. por <span class=\"greek\">ἀπολύτρωσις</span> e prossegue, referindo-se ao costume de realizar anualmente um sacrifício humano em benefício do restante do povo [veja, a respeito, Ltzm. e JWeiss sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:13</a>]: <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἐπέλεγον</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐνιαυτὸν</span> <span class=\"greek\">ἐμβαλλομένῳ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θαλάσσῃ</span> <span class=\"greek\">νεανίᾳ</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀπαλλαγῇ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">συνεχόντων</span> <span class=\"greek\">κακῶν</span>· <span class=\"greek\">περίψημα</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">γενοῦ</span>· <span class=\"greek\">ἤτοι</span> <span class=\"greek\">σωτηρία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπολύτρωσις</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἐνέβαλον</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θαλάσσῃ</span> <span class=\"greek\">ὡσανεὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ποσειδῶνι</span> <span class=\"greek\">θυσίαν</span> <span class=\"greek\">ἀποτιννύντες</span>, «assim falavam sobre o jovem que, conforme o costume anual, era lançado ao mar para libertação das aflições: &#39;Sê nosso meio de purificação; na verdade, nossa salvação e libertação&#39;. Então o lançavam ao mar, como se pagassem integralmente um sacrifício a Poseidon»).<br>Mas é preciso observar também que <span class=\"greek\">περίψ</span>. se tornara cada vez mais uma expressão de autodepreciação cortês, bastante comum na linguagem cotidiana (Dionys. of Alex. em Eus., HE 7, 22, 7 <span class=\"greek\">τὸ</span> <span class=\"greek\">δημῶδες</span> <span class=\"greek\">ῥῆμα</span>. Veja também a inscrição funerária [em WThieling, D. Hellenismus in Kleinafrika 1911, p. 34], na qual uma esposa diz, referindo-se ao marido falecido, <span class=\"greek\">ἐγώ</span> <span class=\"greek\">σου</span> <span class=\"greek\">περίψημα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καλῆς</span> <span class=\"greek\">ψυχῆς</span>); o sentido seria, então, algo como «humildíssimo servidor». Certamente é assim em <span class=\"greek\">περίψ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> IEph 18:1. Mas provavelmente também em 8:1; B 4:9; B 6:5 (veja HVeil: EHennecke, Hdb. zu den ntl. Apokryphen 1904, 218; também JToutain, Nouvelles Études ’35, 144–46).—Frisk s.v. <span class=\"greek\">ψῆν</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περπερεύομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περπερεύομαι</span> (<span class=\"greek\">πέρπερος</span> «vaidoso, presunçoso»; M. Ant. 5, 5, 4; Etym. Mag. p. 665, 37; Hesych. = <span class=\"greek\">κατεπαίρομαι</span>. O composto <span class=\"greek\">ἐμπερπερεύομαι</span> é mais comum: Epict. 2, 1, 34; Cicero, Ad Attic. 1, 14, 4), acumular elogios sobre si mesmo, comportar-se como um <span class=\"greek\">πέρπερος</span> («fanfarrão, falastrão»: Polyb. 32, 2, 5; 39, 1, 2; Epict. 3, 2, 14), vangloriar-se, gabar-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:4</a>.—DELG s.v. <span class=\"greek\">πέρπερος</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Περσίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Περσίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> (inscrição da Palestina: IPeters/HThiersch, Painted Tombs of Marissa 1905, n.os 38 e 41 [II a.C.]; nome usado especialmente para escravas: BGU 895, 29; 31 [II d.C.]; IG VII, 2074; CIL V, 4455), Pérside, destinatária de uma saudação em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:12</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0284-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέρυσι</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέρυσι</span>, antes de vogais <span class=\"greek\">πέρυσιν</span> Hv 2, 1, 3 (sobre o <span class=\"greek\">ν</span>, cf. Lex. Rhet. em RReitzenstein, Index Lect. Rostock 1892/93 p. 6; Schwyzer I 405; B-D-F §20.—Mlt-H. 279), advérbio de tempo (Simonides e outros), no ano passado, há um ano (Aristoph., Pla. e outros; Plut., Mor. 15s.; Philostrat., Her. 33 p. 139, 14 K.; inscrições, papiros) Hv 2, 1, 1; 3. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">π</span>. (BGU 531 II, 1 [70–80 d.C.]; Dssm., NB 48s. [BS 221]), há um ano, desde o ano passado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:10</a>; 9:2.—DELG. M-M.</p></section></article>"};
